SELECT cp.cp_type, d.d_year, SUM(cs.cs_net_paid) AS total_net_paid, (SELECT cr2.cr_return_amount FROM catalog_returns cr2 WHERE cr2.cr_returned_date_sk = 2451019 LIMIT 1) AS sample_return_amount FROM catalog_sales cs JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN catalog_returns cr ON cr.cr_order_number = cs.cs_order_number GROUP BY cp.cp_type, d.d_year HAVING COUNT(*) > 1000
